const slots = {
 industrial:{label:'Industrial flooring',defaultUrl:'/assets/industrial-shivam-grey.webp',alt:'Industrial epoxy flooring'},
 commercial:{label:'Commercial flooring',defaultUrl:'/assets/industrial-shivam-white.webp',alt:'Commercial seamless flooring'},
 decorative:{label:'Residential & decorative flooring',defaultUrl:'/assets/decorative-shivam.webp',alt:'Decorative flooring'},
 parking:{label:'Parking & ramps',defaultUrl:'/assets/parking-shivam.webp',alt:'Parking floor with route markings'},
 waterproofing:{label:'Waterproofing overview',defaultUrl:'/assets/waterproofing-shivam-roof.webp',alt:'Tank, pool and roof waterproofing'},
 food:{label:'Food-processing flooring',defaultUrl:'/assets/industrial-shivam-blue.webp',alt:'Food-processing epoxy/PU flooring'},
 epoxy:{label:'Epoxy flooring finish',defaultUrl:'/assets/industrial-shivam-grey.webp',alt:'Epoxy flooring'},
 pu:{label:'PU flooring finish',defaultUrl:'/assets/industrial-shivam-green.webp',alt:'Industrial flooring'},
 metallic:{label:'Metallic / Italian-style finish',defaultUrl:'/assets/decorative-shivam.webp',alt:'Decorative floor with flowing accents'},
 tank:{label:'Tank waterproofing',defaultUrl:'/assets/waterproofing-shivam-roof.webp',alt:'Tank waterproofing reference'},
 roof:{label:'Roof waterproofing',defaultUrl:'/assets/waterproofing-shivam-roof.webp',alt:'Roof waterproofing reference'},
 pool:{label:'Swimming pool waterproofing',defaultUrl:'/assets/waterproofing-shivam-roof.webp',alt:'Swimming pool waterproofing reference'}
};
slots.textile={label:'Textile & garment',defaultUrl:'/assets/industrial-shivam-grey.webp',alt:'Textile flooring reference'};
slots.pharma={label:'Pharmaceutical',defaultUrl:'/assets/industrial-shivam-light.webp',alt:'Pharmaceutical flooring reference'};
slots.automotive={label:'Automotive',defaultUrl:'/assets/industrial-shivam-green.webp',alt:'Automotive flooring reference'};
slots.warehousing={label:'Warehousing & logistics',defaultUrl:'/assets/industrial-shivam-grey.webp',alt:'Warehouse floor'};
slots.chemical={label:'Chemical industry',defaultUrl:'/assets/industrial-shivam-grey.webp',alt:'Chemical industry flooring reference'};
slots.engineering={label:'Engineering & manufacturing',defaultUrl:'/assets/industrial-shivam-grey.webp',alt:'Industrial flooring'};
slots.esd={label:'ESD flooring',defaultUrl:'/assets/industrial-shivam-grey.webp',alt:'ESD flooring reference'};
slots.dielectric={label:'Dielectric flooring',defaultUrl:'/assets/industrial-shivam-grey.webp',alt:'Dielectric flooring reference'};
const OWNER_EMAIL='shivamvish901@outlook.com';
const signin='/signin-with-chatgpt?return_to=%2Fadmin';
const json=(data,status=200)=>new Response(JSON.stringify(data),{status,headers:{'Content-Type':'application/json; charset=utf-8','Cache-Control':'no-store','X-Content-Type-Options':'nosniff'}});
function authorized(request){return Boolean(request.headers.get('oai-authenticated-user-id'))&&request.headers.get('oai-authenticated-user-email')?.toLowerCase()===OWNER_EMAIL;}
function safeWrite(request){return request.headers.get('Origin')===new URL(request.url).origin;}
async function photoManifest(env){const list=await env.BUCKET.list({prefix:'settings/photos/'});const photos={};await Promise.all(list.objects.map(async item=>{const slot=item.key.split('/').pop();if(slots[slot]){const object=await env.BUCKET.get(item.key);if(object)photos[slot]=await object.json();}}));return photos;}
async function photoRoute(request,env){
 const url=new URL(request.url),path=url.pathname;
 if(path==='/api/photo-session')return json({canEdit:authorized(request),signInUrl:signin});
 if(path==='/api/photos'&&request.method==='GET'){if(!env.BUCKET)return json({error:'Photo storage is unavailable.'},503);return json({slots,photos:await photoManifest(env)});}
 if(path.startsWith('/media/')){
  if(!['GET','HEAD'].includes(request.method))return json({error:'Method not allowed.'},405);
  const key=path.slice(7);if(!/^photos\/[a-z-]+\/[a-f0-9-]+\.(jpg|png|webp|gif)$/.test(key))return new Response('Not found',{status:404});
  const object=await env.BUCKET.get(key);if(!object)return new Response('Not found',{status:404});
  const headers=new Headers();object.writeHttpMetadata(headers);headers.set('Cache-Control','public, max-age=300, must-revalidate');headers.set('X-Content-Type-Options','nosniff');return new Response(request.method==='HEAD'?null:object.body,{headers});
 }
 if(path.startsWith('/api/photos/')){
  if(!['PUT','DELETE'].includes(request.method))return json({error:'Method not allowed.'},405);
  if(!authorized(request))return json({error:'Only the website owner can edit photos.',signInUrl:signin},request.headers.has('oai-authenticated-user-id')?403:401);
  if(!safeWrite(request))return json({error:'Open the photo manager on this website before saving.'},403);
  if(!env.BUCKET)return json({error:'Photo storage is unavailable.'},503);
  const slot=path.split('/').pop();if(!slots[slot])return json({error:'Unknown photo position.'},404);
  if(request.method==='DELETE'){const previousObject=await env.BUCKET.get('settings/photos/'+slot);const previous=previousObject?await previousObject.json():null;if(previous?.url?.startsWith('/media/photos/'+slot+'/'))await env.BUCKET.delete(previous.url.slice(7));await env.BUCKET.delete('settings/photos/'+slot);return json({ok:true});}
  if(request.headers.get('X-Photo-Permission')!=='confirmed')return json({error:'Confirm your permission to publish this photo before uploading.'},400);const max=8*1024*1024;const length=Number(request.headers.get('Content-Length'));if(length>max)return json({error:'Choose an image smaller than 8 MB.'},413);
  const types={'image/jpeg':'jpg','image/png':'png','image/webp':'webp','image/gif':'gif'};const type=request.headers.get('Content-Type')?.split(';')[0];if(!types[type])return json({error:'Use a JPG, PNG, WebP or GIF photo.'},415);
  const reader=request.body?.getReader();if(!reader)return json({error:'Choose a photo first.'},400);const chunks=[];let size=0;while(true){const part=await reader.read();if(part.done)break;size+=part.value.byteLength;if(size>max){await reader.cancel();return json({error:'Choose an image smaller than 8 MB.'},413)}chunks.push(part.value)}if(!size)return json({error:'Choose a photo first.'},400);const joined=new Uint8Array(size);let position=0;for(const chunk of chunks){joined.set(chunk,position);position+=chunk.length}const data=joined.buffer;
  const b=new Uint8Array(data),str=(n,k)=>String.fromCharCode(...b.slice(n,n+k));const matches=(type==='image/jpeg'&&b[0]===255&&b[1]===216&&b[2]===255)||(type==='image/png'&&b[0]===137&&str(1,3)==='PNG')||(type==='image/webp'&&str(0,4)==='RIFF'&&str(8,4)==='WEBP')||(type==='image/gif'&&str(0,3)==='GIF');if(!matches)return json({error:'The file does not match its image format.'},415);
  const previousObject=await env.BUCKET.get('settings/photos/'+slot);const previous=previousObject?await previousObject.json():null;const alt=(url.searchParams.get('alt')||slots[slot].alt).trim().slice(0,200);const key='photos/'+slot+'/'+crypto.randomUUID()+'.'+types[type];
  await env.BUCKET.put(key,data,{httpMetadata:{contentType:type}});const photo={url:'/media/'+key,alt:alt||slots[slot].alt,updatedAt:new Date().toISOString(),publicationPermissionConfirmed:true};await env.BUCKET.put('settings/photos/'+slot,JSON.stringify(photo),{httpMetadata:{contentType:'application/json'}});if(previous?.url?.startsWith('/media/photos/'+slot+'/'))await env.BUCKET.delete(previous.url.slice(7));return json({ok:true,photo});
 }
 return null;
}

const adminHTML="<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width, initial-scale=1\"><title>Photo Manager | Shivam Epoxy Flooring</title><style>*{box-sizing:border-box}body{margin:0;background:#f4f6fb;color:#1d2b4c;font:15px system-ui,sans-serif}header{background:#36476e;color:white;padding:22px 6%;display:flex;justify-content:space-between;gap:20px;align-items:center}a{color:inherit}header a{text-decoration:none;font-size:13px}main{max-width:1100px;margin:40px auto;padding:0 24px}h1{font-size:34px;font-weight:500;margin:0 0 12px}p{line-height:1.6;color:#63728d}.layout{display:grid;grid-template-columns:240px 1fr;gap:30px;margin-top:30px}.slots{display:flex;flex-direction:column;gap:7px;max-height:75vh;overflow:auto}.slots button{text-align:left;border:1px solid #d7dfef;background:white;border-radius:12px;padding:12px;color:#475c82;cursor:pointer;font:inherit;font-size:13px}.slots button[aria-pressed=true]{background:#354871;color:white}.editor{background:white;border:1px solid #dce3ef;border-radius:22px;padding:28px}.preview{border-radius:15px;background:#e9eef7;min-height:250px;display:flex;align-items:center;justify-content:center;overflow:hidden}.preview img{width:100%;height:330px;object-fit:contain;display:block}label{display:block;font-size:13px;margin:20px 0 8px}input[type=text]{width:100%;border:1px solid #afbdd5;border-radius:10px;padding:12px;font:inherit}input[type=file]{max-width:100%;font:inherit}button.action{background:#344771;border:1px solid #344771;border-radius:25px;color:white;padding:12px 21px;font:inherit;cursor:pointer}button.secondary{background:white;color:#344771}button:disabled{opacity:.45;cursor:wait}.actions{display:flex;gap:10px;flex-wrap:wrap;margin-top:24px}.status{padding:14px 0;min-height:48px;line-height:1.5}.status.error{color:#a32f35}.hint{font-size:12px}h2{font-size:24px;font-weight:500;margin-top:0}.notice{background:#e6edf9;padding:15px 20px;border-radius:14px;margin-top:20px}button:focus-visible,a:focus-visible,input:focus-visible{outline:3px solid #90a9df;outline-offset:3px}[hidden]{display:none!important}@media(max-width:700px){.layout{grid-template-columns:1fr}.slots{flex-direction:row;overflow:auto;max-height:none;padding-bottom:10px}.slots button{min-width:160px}.editor{padding:20px}.preview img{height:260px}header{padding:18px 6%}h1{font-size:28px}}html,body{max-width:100%;overflow-x:clip}.layout{grid-template-columns:240px minmax(0,1fr)}.layout>*{min-width:0}.slots{min-width:0;max-width:100%}.editor{min-width:0}.preview{max-width:100%}@media(max-width:700px){.layout{grid-template-columns:minmax(0,1fr)}.slots button{flex:0 0 160px}}input,button{max-width:100%}</style><link rel=\"stylesheet\" href=\"/compliance.css\"></head><body><header><strong>SHIVAM \u00b7 Photo Manager</strong><a href=\"/\" target=\"_blank\" rel=\"noopener\">View website \u2197</a></header><main><h1>Manage your website photos</h1><p>Photo select karein \u2192 preview dekhein \u2192 Save photo par click karein. Saved photos website par sabhi visitors ko dikhenge.</p><div class=\"notice\">JPG, PNG, WebP or GIF \u00b7 Maximum 8 MB per photo. Restore default se pehle wali default image wapas aayegi.</div><div id=\"loading\" class=\"status\" role=\"status\">Loading photos\u2026</div><div class=\"layout\" id=\"layout\" hidden><nav class=\"slots\" id=\"slots\" aria-label=\"Photo positions\"></nav><section class=\"editor\"><h2 id=\"title\"></h2><div class=\"preview\"><img id=\"preview\" alt=\"Selected photo preview\"></div><p id=\"saved-time\" class=\"hint\"></p><form id=\"photo-form\"><label for=\"upload\">Choose a new photo</label><input id=\"upload\" type=\"file\" accept=\"image/jpeg,image/png,image/webp,image/gif\"><label for=\"alt\">Photo description</label><input id=\"alt\" type=\"text\" maxlength=\"200\" placeholder=\"Describe what is in the photo\"><p class=\"hint\">Photo description accessibility aur image samajhne mein madad karti hai.</p><label class=\"consent-line\"><input id=\"photo-permission\" type=\"checkbox\" required><span>I am 18+ and confirm I have the rights and necessary permissions to publish this photo, including any people/site information shown. I have reviewed the <a href=\"/privacy-policy.html\" target=\"_blank\" rel=\"noopener\">Privacy Policy</a>.</span></label><div class=\"actions\"><button class=\"action\" id=\"save\" type=\"submit\" disabled>Save photo</button><button class=\"action secondary\" id=\"restore\" type=\"button\">Restore default</button><button class=\"action secondary\" id=\"cancel\" type=\"button\" disabled>Cancel selection</button></div></form><div id=\"status\" class=\"status\" role=\"status\" aria-live=\"polite\"></div></section></div></main><script>\nlet state,selected,pending,previewURL,busy=false,selectionVersion=0;\nconst $=s=>document.querySelector(s);function message(text,error=false){$('#status').textContent=text;$('#status').classList.toggle('error',error)}\nfunction discard(){selectionVersion++;if($('#photo-permission'))$('#photo-permission').checked=false;if(previewURL)URL.revokeObjectURL(previewURL);previewURL=null;pending=null;$('#upload').value='';$('#save').disabled=true;$('#cancel').disabled=true}\nfunction render(){const slot=state.slots[selected],photo=state.photos[selected];$('#title').textContent=slot.label;$('#preview').src=photo?.url||slot.defaultUrl;$('#alt').value=photo?.alt||slot.alt;$('#saved-time').textContent=photo?'Last saved: '+new Date(photo.updatedAt).toLocaleString():'Using the default website photo.';document.querySelectorAll('[data-slot]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.slot===selected)));$('#restore').disabled=!photo||busy}\nfunction select(key){if(busy)return;$('#photo-permission').checked=false;discard();selected=key;render();message('')}\nfunction setBusy(value){busy=value;document.querySelectorAll('button,input').forEach(el=>el.disabled=value);if(!value){$('#save').disabled=!pending;$('#cancel').disabled=!pending;$('#restore').disabled=!state.photos[selected]}}\nasync function api(url,options){const response=await fetch(url,{...options,credentials:'same-origin'});let data;try{data=await response.json()}catch{throw new Error('The server could not complete this request. Please retry.')}if(!response.ok)throw new Error(data.error||'Unable to save. Please retry.');return data}\n$('#upload').addEventListener('change',async()=>{const file=$('#upload').files[0];if(!file)return;discard();if(!['image/jpeg','image/png','image/webp','image/gif'].includes(file.type)||file.size>8*1024*1024){message('Choose a JPG, PNG, WebP or GIF smaller than 8 MB.',true);return}const version=selectionVersion;const url=URL.createObjectURL(file);try{const image=new Image();image.src=url;await image.decode();if(version!==selectionVersion){URL.revokeObjectURL(url);return}pending=file;previewURL=url;$('#preview').src=url;$('#save').disabled=false;$('#cancel').disabled=false;message('Preview only. Click Save photo to update the website.')}catch{URL.revokeObjectURL(url);message('This file could not be opened as an image.',true)}});\n$('#cancel').addEventListener('click',()=>{discard();render();message('Selection cancelled. The saved photo has not changed.')});\n$('#photo-form').addEventListener('submit',async e=>{e.preventDefault();if(!pending||busy)return;if(!$('#photo-permission').checked){$('#photo-permission').reportValidity();return}setBusy(true);message('Uploading and saving\u2026');try{const result=await api('/api/photos/'+selected+'?alt='+encodeURIComponent($('#alt').value),{method:'PUT',headers:{'Content-Type':pending.type,'X-Photo-Permission':'confirmed'},body:pending});state.photos[selected]=result.photo;discard();render();message('Saved. The website photo is updated. Refresh an open website tab to see it.')}catch(error){message(error.message,true)}finally{setBusy(false)}});\n$('#restore').addEventListener('click',async()=>{if(busy||!confirm('Restore the default photo for '+state.slots[selected].label+'?'))return;setBusy(true);message('Restoring default\u2026');try{await api('/api/photos/'+selected,{method:'DELETE'});delete state.photos[selected];discard();render();message('Default photo restored.')}catch(error){message(error.message,true)}finally{setBusy(false)}});\nwindow.addEventListener('beforeunload',e=>{if(pending){e.preventDefault();e.returnValue=''}});\n(async()=>{try{state=await api('/api/photos');for(const [key,slot] of Object.entries(state.slots)){const b=document.createElement('button');b.type='button';b.dataset.slot=key;b.textContent=slot.label;b.addEventListener('click',()=>{if(pending&&!confirm('Discard the unsaved photo selection?'))return;select(key)});$('#slots').append(b)}$('#loading').hidden=true;$('#layout').hidden=false;select(Object.keys(state.slots)[0])}catch(error){$('#loading').textContent=error.message}})();\n</script></body></html>\n";

const sourceArchiveBase64 = '';

export default {async fetch(request,env){try{const url=new URL(request.url);if(url.pathname==='/admin/source-download'){if(!request.headers.get('oai-authenticated-user-id'))return Response.redirect(url.origin+'/signin-with-chatgpt?return_to=%2Fadmin%2Fsource-download',302);if(!authorized(request))return new Response('Only the website owner can download source code.',{status:403,headers:{'Cache-Control':'no-store'}});if(!['GET','HEAD'].includes(request.method))return new Response('Method not allowed',{status:405});const bytes=Uint8Array.from(atob(sourceArchiveBase64),c=>c.charCodeAt(0));return new Response(request.method==='HEAD'?null:bytes,{headers:{'Content-Type':'application/zip','Content-Disposition':'attachment; filename="Shivam-Epoxy-Flooring-Complete-Source.zip"','Content-Length':String(bytes.byteLength),'Cache-Control':'private, no-store','X-Content-Type-Options':'nosniff'}});} if(url.pathname.startsWith('/api/')||url.pathname.startsWith('/media/')){return await photoRoute(request,env)||new Response('Not found',{status:404});}if(url.pathname==='/admin'||url.pathname==='/admin/'){if(!request.headers.get('oai-authenticated-user-id'))return Response.redirect(url.origin+'/signin-with-chatgpt?return_to=%2Fadmin',302);if(!authorized(request))return new Response('Only the website owner can manage photos.',{status:403,headers:{'Cache-Control':'no-store'}});return new Response(adminHTML,{headers:{'Content-Type':'text/html; charset=utf-8','Cache-Control':'no-store','X-Frame-Options':'SAMEORIGIN','X-Content-Type-Options':'nosniff'}});}if(!env.ASSETS)return new Response('Website assets unavailable',{status:503});if(url.pathname==='/'||url.pathname==='/index.html')url.pathname='/index.html';else if(/^\/services\/[a-z-]+$/.test(url.pathname)||['/about','/process','/privacy-policy','/terms-of-service','/cancellation-refund-policy','/cookie-policy','/consumer-service-terms','/business-service-terms','/contact'].includes(url.pathname))url.pathname+='.html';return env.ASSETS.fetch(new Request(url,request));}catch(error){return new Response('Something went wrong. Please try again.',{status:500,headers:{'Cache-Control':'no-store'}});}}};